begin;
select set_config('app.sample_company_id',gen_random_uuid()::text,true);
select set_config('app.sample_operator_id',gen_random_uuid()::text,true);
select set_config('app.sample_reader_id',gen_random_uuid()::text,true);
select set_config('app.sample_outsider_id',gen_random_uuid()::text,true);
insert into auth.users(id,aud,role,email,email_confirmed_at,raw_app_meta_data,raw_user_meta_data,created_at,updated_at)
 select current_setting(setting)::uuid,'authenticated','authenticated','sample+'||current_setting(setting)||'@invalid.test',now(),'{"provider":"email","providers":["email"]}'::jsonb,'{"display_name":"SAMPLE Operator"}'::jsonb,now(),now()
 from unnest(array['app.sample_operator_id','app.sample_reader_id','app.sample_outsider_id']) setting;
insert into public.companies(id,name,created_by) values(current_setting('app.sample_company_id')::uuid,'SAMPLE Item Controls Factory',current_setting('app.sample_operator_id')::uuid);
insert into public.plants(company_id,name) values(current_setting('app.sample_company_id')::uuid,'SAMPLE Plant');
insert into public.company_memberships(company_id,user_id) select current_setting('app.sample_company_id')::uuid,current_setting(setting)::uuid from unnest(array['app.sample_operator_id','app.sample_reader_id']) setting;
insert into public.user_company_roles(company_id,user_id,role) values(current_setting('app.sample_company_id')::uuid,current_setting('app.sample_operator_id')::uuid,'admin'),(current_setting('app.sample_company_id')::uuid,current_setting('app.sample_reader_id')::uuid,'planning');
set local role authenticated;
select set_config('request.jwt.claim.sub',current_setting('app.sample_operator_id'),true);
do $$
declare c uuid:=current_setting('app.sample_company_id')::uuid;i uuid;other_item uuid;cust uuid;supplier uuid;wh uuid;loc uuid;s1 uuid;s2 uuid;u1 uuid;u2 uuid;req uuid;po uuid;receipt uuid;rfq uuid;q uuid;so uuid;payload jsonb;line uuid;lot uuid;plan uuid;reservation uuid;shipment uuid;package uuid;
begin
 insert into public.items(company_id,sku,description,base_uom) values(c,'SAMPLE-SPEC','SAMPLE Bolt','pcs') returning id into i;
 insert into public.items(company_id,sku,description,base_uom) values(c,'SAMPLE-OTHER','SAMPLE Other','pcs') returning id into other_item;
 insert into public.customers(company_id,code,name) values(c,'SAMPLE-C','SAMPLE Customer') returning id into cust;
 insert into public.suppliers(company_id,code,name) values(c,'SAMPLE-S','SAMPLE Supplier') returning id into supplier;
 insert into public.warehouses(company_id,plant_id,code,name) select c,id,'SAMPLE-WH','SAMPLE Warehouse' from public.plants where company_id=c returning id into wh;
 insert into public.stock_locations(company_id,warehouse_id,code,name) values(c,wh,'SAMPLE-L','SAMPLE Location') returning id into loc;
 payload:=jsonb_build_object('item_id',i,'product_type','SAMPLE bolt','diameter_mm','8.000001','length_mm','30','thread_pitch_mm','1.25','thread_designation','SAMPLE thread','material_grade','SAMPLE material','property_class','SAMPLE class','coating','SAMPLE finish','standard_reference','SAMPLE standard','evidence','SAMPLE drawing evidence');
 s1:=public.item_control_command(c,'create_specification',payload,'spec-create');
 if public.item_control_command(c,'create_specification',payload,'spec-create')<>s1 then raise exception 'SAMPLE_SPEC_RETRY_CHANGED';end if;
 begin perform public.item_control_command(c,'create_specification',jsonb_set(payload,'{length_mm}','"31"'),'spec-create');raise exception 'SAMPLE_SPEC_KEY_REUSE';exception when others then if sqlerrm<>'IDEMPOTENCY_CONFLICT' then raise;end if;end;
 perform public.item_control_command(c,'approve_specification',jsonb_build_object('id',s1,'reason','SAMPLE checked'),'spec-ok');
 rfq:=public.create_rfq(c,'SAMPLE-RFQ',cust,'SAMPLE requirement',jsonb_build_array(jsonb_build_object('item_id',i,'requested_description','SAMPLE bolt','quantity','20','uom','pcs')),'rfq');
 perform public.record_feasibility(c,rfq,'feasible',null,null,null,'SAMPLE checked',1,'feas');
 q:=public.create_quotation(c,rfq,'SAMPLE-Q','INR',current_date+30,jsonb_build_array(jsonb_build_object('item_id',i,'quantity','20','uom','pcs','unit_price','1')),'quote');
 select id into line from public.quotation_lines where quotation_id=q;
 if (select item_specification_id from public.quotation_lines where id=line) is distinct from s1 then raise exception 'SAMPLE_SPEC_NOT_PINNED';end if;
 perform public.approve_quotation(c,q,1,'approve-q');
 perform public.item_control_command(c,'retire_specification',jsonb_build_object('id',s1,'reason','SAMPLE revised drawing'),'retire-spec');
 s2:=public.item_control_command(c,'create_specification',jsonb_set(payload,'{length_mm}','"31"'),'spec-next');
 perform public.item_control_command(c,'approve_specification',jsonb_build_object('id',s2,'reason','SAMPLE checked revision'),'spec-next-ok');
 so:=public.accept_quotation_create_sales_order(c,q,'SAMPLE-SO','SAMPLE-PO',current_date+7,2,'accept');
 if (select item_specification_id from public.sales_order_lines where sales_order_id=so) is distinct from s1 then raise exception 'SAMPLE_OLD_ORDER_REBOUND';end if;
 payload:=jsonb_build_object('item_id',i,'from_uom','box','from_quantity','1','to_quantity','10','evidence','SAMPLE verified sealed ten-piece box');
 u1:=public.item_control_command(c,'create_conversion',payload,'unit');
 req:=public.request_material(c,'SAMPLE-REQ',i,20,'pcs','SAMPLE replenishment',current_date,null,'req');
 po:=public.create_purchase_order(c,req,supplier,'SAMPLE-PO',1,'INR',current_date,1,'po');
 perform public.approve_purchase_order(c,po,1,'po-ok');
 payload:=jsonb_build_object('order_id',po,'number','SAMPLE-GRN','lot_code','SAMPLE-LOT','supplier_lot','SAMPLE heat','location_id',loc,'quantity','2','uom','box','expected_revision',2,'conversion_id',u1);
 begin perform public.receive_purchase_order_in_unit(c,payload,'draft-unit');raise exception 'SAMPLE_DRAFT_UNIT_POSTED';exception when others then if sqlerrm<>'CONVERSION_NOT_APPROVED' then raise;end if;end;
 perform public.item_control_command(c,'approve_conversion',jsonb_build_object('id',u1,'reason','SAMPLE counted basis'),'unit-ok');
 begin perform public.receive_purchase_order_in_unit(c,jsonb_set(payload,'{quantity}','"0.15"'),'fractional');raise exception 'SAMPLE_FRACTIONAL_PIECES_POSTED';exception when others then if sqlerrm<>'CONVERSION_PRECISION_LOSS' then raise;end if;end;
 receipt:=public.receive_purchase_order_in_unit(c,payload,'receive-unit');
 select lot_id into lot from public.goods_receipts where id=receipt;
 if not exists(select 1 from public.goods_receipts where id=receipt and quantity=20 and uom='pcs') or not exists(select 1 from public.unit_conversion_events where entity_id=receipt and input_quantity=2 and input_uom='box' and base_quantity=20) then raise exception 'SAMPLE_RECEIPT_CONVERSION_MISSING';end if;
 if public.receive_purchase_order_in_unit(c,payload,'receive-unit')<>receipt then raise exception 'SAMPLE_RECEIPT_RETRY_CHANGED';end if;
 plan:=public.quality_command(c,'create_plan',jsonb_build_object('item_id',i,'label','SAMPLE Incoming','version','A','sample_size',1,'characteristics','[{"key":"condition","label":"SAMPLE condition","type":"attribute","expected":"PASS"}]'::jsonb),'plan');
 perform public.quality_command(c,'approve_plan',jsonb_build_object('plan_id',plan),'plan-ok');
 perform public.quality_command(c,'inspect',jsonb_build_object('plan_id',plan,'lot_id',lot,'kind','incoming','revision',1,'readings','[{"key":"condition","values":["PASS"]}]'::jsonb,'reason','SAMPLE checked'),'inspect');
 perform public.release_stock_lot(c,lot,1,'release');
 select id into line from public.sales_order_lines where sales_order_id=so;
 reservation:=public.reserve_finished_goods(c,line,lot,20,1,'reserve');
 shipment:=public.prepare_packing_shipment(c,so,'SAMPLE-PACK','SAMPLE-SHIP',jsonb_build_array(jsonb_build_object('reservation_id',reservation,'quantity','20')),2,'packing');
 select id into line from public.shipment_lines where shipment_id=shipment;
 package:=public.add_shipment_package_in_unit(c,jsonb_build_object('shipment_line_id',line,'shipment_revision',1,'quantity','2','uom','box','conversion_id',u1,'package_code','SAMPLE-BOX'),'package');
 if not exists(select 1 from jsonb_array_elements(public.get_packing_workspace(c)->'packages') p where (p->>'id')::uuid=package and p->>'input_quantity'='2.000000') then raise exception 'SAMPLE_PACK_CONVERSION_MISSING';end if;
 perform public.item_control_command(c,'retire_conversion',jsonb_build_object('id',u1,'reason','SAMPLE packing correction'),'unit-retire');
 if public.receive_purchase_order_in_unit(c,payload,'receive-unit')<>receipt then raise exception 'SAMPLE_RETIRED_RETRY_CHANGED';end if;
 begin perform public.receive_purchase_order_in_unit(c,payload,'retired-receipt');raise exception 'SAMPLE_RETIRED_UNIT_POSTED';exception when others then if sqlerrm<>'CONVERSION_NOT_APPROVED' then raise;end if;end;
 u2:=public.item_control_command(c,'create_conversion',jsonb_build_object('item_id',i,'from_uom','kg','from_quantity','3','to_quantity','1','evidence','SAMPLE measured basis'),'kg');
 perform public.item_control_command(c,'approve_conversion',jsonb_build_object('id',u2,'reason','SAMPLE measured'),'kg-ok');
 begin perform public.receive_purchase_order_in_unit(c,jsonb_set(jsonb_set(jsonb_set(payload,'{conversion_id}',to_jsonb(u2)),'{quantity}','"1"'),'{uom}','"kg"'),'rounded');raise exception 'SAMPLE_CONVERSION_ROUNDED';exception when others then if sqlerrm<>'CONVERSION_PRECISION_LOSS' then raise;end if;end;
 perform set_config('request.jwt.claim.sub',current_setting('app.sample_reader_id'),true);
 if jsonb_array_length(public.get_item_controls(c)->'specifications')<>2 then raise exception 'SAMPLE_SPEC_HISTORY_MISSING';end if;
 begin perform public.item_control_command(c,'retire_specification',jsonb_build_object('id',s2,'reason','SAMPLE denied'),'reader');raise exception 'SAMPLE_READER_APPROVED';exception when others then if sqlerrm<>'FORBIDDEN' then raise;end if;end;
 begin update public.item_specification_versions set product_type='SAMPLE forged' where id=s1;raise exception 'SAMPLE_DIRECT_SPEC_WRITE';exception when insufficient_privilege then null;end;
 perform set_config('request.jwt.claim.sub',current_setting('app.sample_outsider_id'),true);
 if exists(select 1 from public.item_specification_versions where company_id=c) then raise exception 'SAMPLE_SPEC_TENANT_LEAK';end if;
 begin perform public.get_item_controls(c);raise exception 'SAMPLE_CONTROL_LEAK';exception when others then if sqlerrm<>'FORBIDDEN' then raise;end if;end;
end $$;
rollback;
